// GÉNÉRÉ PAR scripts/embed-assets.mjs — NE PAS ÉDITER À LA MAIN.
// Copies (imports réécrits) des sources gelées + runtime compilateur,
// embarquées pour garder le chemin de compilation PUR (zéro fs).
// Non-dérive garantie par tests/embedded-assets.test.ts.
export const EMBEDDED_ASSETS: Readonly<Record<string, string>> = {
  "lib/blocks/components.tsx": "// LES 6 SMART BLOCKS v1 — composites DE PRIMITIVES exclusivement (D-023).\n// RÈGLE MÉCANISÉE (tests/etancheite-ratchet.test.ts) : tout le visuel passe\n// par @deribfy/primitives ; seul composant react-native autorisé ici :\n// FlatList (structurel). AUCUN StyleSheet, AUCUN style en dur — le moteur\n// de styling reste remplaçable (D-021) et les tokens restent la seule\n// source visuelle. AUCUNE syntaxe Maestro/Detox : les blocs sont\n// E2E-agnostiques (D-022/D-023), seuls les testID standard sont exposés.\nimport { FlatList } from \"react-native\";\nimport {\n  AppButton,\n  AppText,\n  Badge,\n  ListRow,\n  Section,\n  StateView,\n  TextField,\n} from \"../primitives\";\nimport type {\n  Blocks,\n  ButtonBlockProps,\n  DetailHeaderBlockProps,\n  EmptyStateBlockProps,\n  FormBlockProps,\n  HeaderBlockProps,\n  ListBlockProps,\n} from \"./contracts.ts\";\n\nexport function HeaderBlock({ title, subtitle, testID }: HeaderBlockProps) {\n  return (\n    <Section testID={testID}>\n      <AppText variant=\"heading\">{title}</AppText>\n      {subtitle !== undefined && <AppText tone=\"muted\">{subtitle}</AppText>}\n    </Section>\n  );\n}\n\nexport function ListBlock({\n  title,\n  items,\n  state = { kind: \"ready\" },\n  onItemPress,\n  testID,\n}: ListBlockProps) {\n  if (state.kind === \"loading\") {\n    return <StateView state=\"loading\" title={state.title} testID={testID} />;\n  }\n  if (state.kind === \"empty\") {\n    return (\n      <StateView state=\"empty\" title={state.title} message={state.message} testID={testID} />\n    );\n  }\n  if (state.kind === \"error\") {\n    return (\n      <StateView\n        state=\"error\"\n        title={state.title}\n        message={state.message}\n        actionLabel={state.retryLabel}\n        onAction={state.onRetry}\n        testID={testID}\n      />\n    );\n  }\n  return (\n    <Section title={title} testID={testID}>\n      <FlatList\n        data={items}\n        keyExtractor={(item) => item.id}\n        renderItem={({ item }) => (\n          <ListRow\n            title={item.title}\n            subtitle={item.subtitle}\n            trailing={item.trailing}\n            badge={item.badge}\n            onPress={\n              onItemPress === undefined\n                ? undefined\n                : () => {\n                    onItemPress(item.id);\n                  }\n            }\n            testID={`${testID ?? \"list\"}-row-${item.id}`}\n          />\n        )}\n      />\n    </Section>\n  );\n}\n\nexport function FormBlock({\n  title,\n  fields,\n  values,\n  onChangeField,\n  submitLabel,\n  onSubmit,\n  state = \"ready\",\n  errorMessage,\n  fieldErrors,\n  testID,\n}: FormBlockProps) {\n  return (\n    <Section title={title} testID={testID}>\n      {fields.map((field) => (\n        <TextField\n          key={field.id}\n          label={field.label}\n          placeholder={field.placeholder}\n          secure={field.secure}\n          value={values[field.id] ?? \"\"}\n          onChangeText={(v) => {\n            onChangeField(field.id, v);\n          }}\n          error={fieldErrors?.[field.id]}\n          testID={`${testID ?? \"form\"}-field-${field.id}`}\n        />\n      ))}\n      {state === \"error\" && errorMessage !== undefined && (\n        <AppText tone=\"error\" testID={`${testID ?? \"form\"}-error`}>\n          {errorMessage}\n        </AppText>\n      )}\n      <AppButton\n        label={submitLabel}\n        onPress={onSubmit}\n        loading={state === \"submitting\"}\n        testID={`${testID ?? \"form\"}-submit`}\n      />\n    </Section>\n  );\n}\n\nexport function ButtonBlock({ label, kind, onPress, testID }: ButtonBlockProps) {\n  return <AppButton label={label} kind={kind} onPress={onPress} testID={testID} />;\n}\n\nexport function EmptyStateBlock({\n  title,\n  message,\n  actionLabel,\n  onAction,\n  testID,\n}: EmptyStateBlockProps) {\n  return (\n    <StateView\n      state=\"empty\"\n      title={title}\n      message={message}\n      actionLabel={actionLabel}\n      onAction={onAction}\n      testID={testID}\n    />\n  );\n}\n\nexport function DetailHeaderBlock({\n  title,\n  subtitle,\n  badges,\n  trailing,\n  testID,\n}: DetailHeaderBlockProps) {\n  return (\n    <Section testID={testID}>\n      <AppText variant=\"heading\">{title}</AppText>\n      {subtitle !== undefined && <AppText tone=\"muted\">{subtitle}</AppText>}\n      {trailing !== undefined && (\n        <AppText variant=\"title\" tone=\"primary\">\n          {trailing}\n        </AppText>\n      )}\n      {badges?.map((badge) => <Badge key={badge} label={badge} />)}\n    </Section>\n  );\n}\n\n// Conformité au contrat vérifiée par le compilateur (patron 3.2 / banc P-003).\nexport const blocks: Blocks = {\n  HeaderBlock,\n  ListBlock,\n  FormBlock,\n  ButtonBlock,\n  EmptyStateBlock,\n  DetailHeaderBlock,\n};\n",
  "lib/blocks/contracts.ts": "// CONTRATS COMPORTEMENTAUX DES SMART BLOCKS v1 (ROADMAP Phase 3.3, D-023 —\n// registre de blocs COMPOSITES DE PRIMITIVES, granularité section d'écran).\n//\n// RÈGLE D'ÉTANCHÉITÉ (§22, D-021 — même cliquet que les primitives) : ce\n// fichier n'importe QUE des types de `react`. Aucun type de styling, aucun\n// type react-native — le moteur de styling ET le moteur E2E restent\n// remplaçables sans toucher aux contrats des blocs.\n//\n// Les ÉTATS (loading/empty/error) sont EXPLICITES et contractuels : le bloc\n// ne déduit jamais son état de ses données (déterminisme — c'est le\n// compilateur/runtime qui décide de l'état, jamais une heuristique).\nimport type { ComponentType } from \"react\";\n\nexport interface BlockA11yProps {\n  testID?: string;\n}\n\nexport interface HeaderBlockProps extends BlockA11yProps {\n  title: string;\n  subtitle?: string;\n}\n\nexport interface ListItemData {\n  id: string;\n  title: string;\n  subtitle?: string;\n  trailing?: string;\n  badge?: string;\n}\n\n// F3 (revue pré-gel 2026-08-28) : état DISCRIMINÉ — les libellés d'état\n// sont REQUIS exactement quand l'état les rend, et FOURNIS par l'appelant\n// (le compilateur, depuis l'AIR/les locales). AUCUN texte par défaut dans\n// le moteur : une chaîne codée en dur fuiterait la langue du moteur dans\n// des apps de langue arbitraire (i18n structurel, non-négociable 16).\nexport type ListBlockState =\n  | { kind: \"ready\" }\n  | { kind: \"loading\"; title: string }\n  | { kind: \"empty\"; title: string; message?: string }\n  | {\n      kind: \"error\";\n      title: string;\n      message?: string;\n      retryLabel?: string;\n      onRetry?: () => void;\n    };\n\nexport interface ListBlockProps extends BlockA11yProps {\n  title?: string;\n  items: readonly ListItemData[];\n  /** État EXPLICITE (défaut { kind: \"ready\" }) — jamais déduit des données. */\n  state?: ListBlockState;\n  onItemPress?: (itemId: string) => void;\n}\n\nexport interface FormFieldSpec {\n  id: string;\n  label: string;\n  placeholder?: string;\n  secure?: boolean;\n}\n\nexport type FormBlockState = \"ready\" | \"submitting\" | \"error\";\n\nexport interface FormBlockProps extends BlockA11yProps {\n  title?: string;\n  fields: readonly FormFieldSpec[];\n  values: Readonly<Record<string, string>>;\n  onChangeField: (fieldId: string, value: string) => void;\n  submitLabel: string;\n  onSubmit: () => void;\n  /** État EXPLICITE (défaut \"ready\"). */\n  state?: FormBlockState;\n  errorMessage?: string;\n  fieldErrors?: Readonly<Record<string, string>>;\n}\n\nexport interface ButtonBlockProps extends BlockA11yProps {\n  label: string;\n  kind?: \"primary\" | \"ghost\";\n  onPress: () => void;\n}\n\nexport interface EmptyStateBlockProps extends BlockA11yProps {\n  title: string;\n  message?: string;\n  actionLabel?: string;\n  onAction?: () => void;\n}\n\nexport interface DetailHeaderBlockProps extends BlockA11yProps {\n  title: string;\n  subtitle?: string;\n  badges?: readonly string[];\n  trailing?: string;\n}\n\n// Le record complet — la conformité de l'implémentation est vérifiée par le\n// compilateur TypeScript (patron des primitives 3.2 et du banc P-003).\nexport interface Blocks {\n  HeaderBlock: ComponentType<HeaderBlockProps>;\n  ListBlock: ComponentType<ListBlockProps>;\n  FormBlock: ComponentType<FormBlockProps>;\n  ButtonBlock: ComponentType<ButtonBlockProps>;\n  EmptyStateBlock: ComponentType<EmptyStateBlockProps>;\n  DetailHeaderBlock: ComponentType<DetailHeaderBlockProps>;\n}\n",
  "lib/primitives/contracts.ts": "// CONTRATS DE PRIMITIVES v1 (ROADMAP Phase 3.2 — dossier d'options validé\n// par le propriétaire : A1+B2+C2+D1).\n//\n// RÈGLE D'ÉTANCHÉITÉ (ARCHITECTURE §22, D-021, prouvée 6/6 au banc P-003,\n// verrouillée par tests/contracts-ratchet.test.ts) : ce fichier n'importe\n// QUE des types de `react`. Aucun type de bibliothèque de styling, aucun\n// type react-native, aucune valeur — le moteur de styling reste remplaçable\n// sans toucher ni aux contrats, ni aux blocs, ni à l'AIR.\n//\n// Surface a11y minimale (C2) : `testID` partout ; `accessibilityLabel` sur\n// les primitives interactives/informatives. Les RÔLES a11y sont posés par\n// l'implémentation (détail interne, pas contractuel).\nimport type { ComponentType, PropsWithChildren, ReactNode } from \"react\";\n\nexport type Scheme = \"light\" | \"dark\";\n\nexport interface A11yProps {\n  testID?: string;\n  accessibilityLabel?: string;\n}\n\n// Les 4 variantes de texte = les 4 tokens de police de la source unique.\nexport type TextVariant = \"label\" | \"body\" | \"title\" | \"heading\";\nexport type TextTone = \"default\" | \"muted\" | \"primary\" | \"error\" | \"success\" | \"warn\";\n\nexport type AppTextProps = PropsWithChildren<\n  A11yProps & {\n    variant?: TextVariant;\n    tone?: TextTone;\n    /** Alignement LOGIQUE (miroir RTL automatique) — jamais left/right. */\n    align?: \"start\" | \"center\" | \"end\";\n  }\n>;\n\nexport type ScreenShellProps = PropsWithChildren<A11yProps & { title: string }>;\n\nexport type SectionProps = PropsWithChildren<A11yProps & { title?: string }>;\n\nexport interface AppButtonProps extends A11yProps {\n  label: string;\n  onPress: () => void;\n  kind?: \"primary\" | \"ghost\";\n  disabled?: boolean;\n  loading?: boolean;\n}\n\nexport interface TextFieldProps extends A11yProps {\n  label: string;\n  value: string;\n  onChangeText: (value: string) => void;\n  placeholder?: string;\n  error?: string;\n  loading?: boolean;\n  /** Saisie masquée (AuthFlow — mot de passe). */\n  secure?: boolean;\n}\n\nexport interface ListRowProps extends A11yProps {\n  title: string;\n  subtitle?: string;\n  badge?: string;\n  /** Texte de fin de ligne (prix, valeur, méta) — position logique RTL. */\n  trailing?: string;\n  /** Contenu de tête de ligne fourni par le bloc (avatar, icône…). */\n  leading?: ReactNode;\n  onPress?: () => void;\n}\n\nexport interface BadgeProps extends A11yProps {\n  label: string;\n  tone?: \"info\" | \"success\" | \"warn\" | \"error\";\n}\n\nexport interface StateViewProps extends A11yProps {\n  state: \"loading\" | \"empty\" | \"error\";\n  title: string;\n  message?: string;\n  actionLabel?: string;\n  onAction?: () => void;\n}\n\nexport interface SpinnerProps extends A11yProps {\n  size?: \"small\" | \"large\";\n}\n\n// Le record complet — la conformité d'une implémentation est vérifiée par\n// le compilateur TypeScript (patron éprouvé au banc P-003).\nexport interface Primitives {\n  ScreenShell: ComponentType<ScreenShellProps>;\n  Section: ComponentType<SectionProps>;\n  AppText: ComponentType<AppTextProps>;\n  AppButton: ComponentType<AppButtonProps>;\n  TextField: ComponentType<TextFieldProps>;\n  ListRow: ComponentType<ListRowProps>;\n  Badge: ComponentType<BadgeProps>;\n  StateView: ComponentType<StateViewProps>;\n  Spinner: ComponentType<SpinnerProps>;\n}\n\nexport interface ThemeBridge {\n  scheme: Scheme;\n  setScheme: (scheme: Scheme) => void;\n}\n",
  "lib/primitives/index.ts": "// @deribfy/primitives — contrats v1 + implémentation StyleSheet+tokens (D-021).\nexport type {\n  A11yProps,\n  AppButtonProps,\n  AppTextProps,\n  BadgeProps,\n  ListRowProps,\n  Primitives,\n  Scheme,\n  ScreenShellProps,\n  SectionProps,\n  SpinnerProps,\n  StateViewProps,\n  TextFieldProps,\n  TextTone,\n  TextVariant,\n  ThemeBridge,\n} from \"./contracts.ts\";\nexport {\n  AppButton,\n  AppText,\n  Badge,\n  ListRow,\n  primitives,\n  ScreenShell,\n  Section,\n  Spinner,\n  StateView,\n  TextField,\n} from \"./primitives.tsx\";\nexport { ThemeRoot, useThemeBridge } from \"./theme-bridge.tsx\";\n",
  "lib/primitives/primitives.tsx": "// LES 9 PRIMITIVES v1 (dossier 3.2 validé : B2) — implémentation\n// StyleSheet + tokens maison (D-021). Simple et composable, sans mécanisme\n// « au cas où » : chaque primitive est exigée par un bloc de 3.3 ou par le\n// harnais 3.4. Les rôles a11y sont posés ici (C2) ; les contrats n'exposent\n// que testID/accessibilityLabel.\nimport { ActivityIndicator, Pressable, Text, TextInput, View } from \"react-native\";\nimport type {\n  AppButtonProps,\n  AppTextProps,\n  BadgeProps,\n  ListRowProps,\n  Primitives,\n  ScreenShellProps,\n  SectionProps,\n  SpinnerProps,\n  StateViewProps,\n  TextFieldProps,\n  TextVariant,\n} from \"./contracts.ts\";\nimport { useStyles } from \"./theme-bridge.tsx\";\nimport type { Sheet } from \"./styles.ts\";\n\nconst VARIANT_STYLE: Record<TextVariant, keyof Sheet> = {\n  label: \"textLabel\",\n  body: \"textBody\",\n  title: \"textTitle\",\n  heading: \"textHeading\",\n};\n\nexport function ScreenShell({ title, children, testID, accessibilityLabel }: ScreenShellProps) {\n  const s = useStyles();\n  return (\n    <View style={s.shell} testID={testID} accessibilityLabel={accessibilityLabel}>\n      <Text style={s.shellTitle} accessibilityRole=\"header\">\n        {title}\n      </Text>\n      {children}\n    </View>\n  );\n}\n\nexport function Section({ title, children, testID, accessibilityLabel }: SectionProps) {\n  const s = useStyles();\n  return (\n    <View style={s.section} testID={testID} accessibilityLabel={accessibilityLabel}>\n      {title !== undefined && <Text style={s.sectionTitle}>{title}</Text>}\n      {children}\n    </View>\n  );\n}\n\nexport function AppText({\n  variant = \"body\",\n  tone = \"default\",\n  align,\n  children,\n  testID,\n  accessibilityLabel,\n}: AppTextProps) {\n  const s = useStyles();\n  return (\n    <Text\n      style={[\n        s[VARIANT_STYLE[variant]],\n        tone === \"muted\" && s.toneMuted,\n        tone === \"primary\" && s.tonePrimary,\n        tone === \"error\" && s.toneError,\n        tone === \"success\" && s.toneSuccess,\n        tone === \"warn\" && s.toneWarn,\n        align === \"center\" && s.alignCenter,\n        align === \"end\" && s.alignEnd,\n      ]}\n      testID={testID}\n      accessibilityLabel={accessibilityLabel}\n    >\n      {children}\n    </Text>\n  );\n}\n\nexport function AppButton({\n  label,\n  onPress,\n  kind = \"primary\",\n  disabled = false,\n  loading = false,\n  testID,\n  accessibilityLabel,\n}: AppButtonProps) {\n  const s = useStyles();\n  const ghost = kind === \"ghost\";\n  const inactive = disabled || loading;\n  return (\n    <Pressable\n      style={[s.button, ghost && s.buttonGhost, inactive && s.buttonDisabled]}\n      onPress={inactive ? undefined : onPress}\n      disabled={inactive}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? label}\n      accessibilityState={{ disabled: inactive, busy: loading }}\n    >\n      {loading && <ActivityIndicator size=\"small\" />}\n      <Text style={[s.buttonText, ghost && s.buttonGhostText]}>{label}</Text>\n    </Pressable>\n  );\n}\n\nexport function TextField({\n  label,\n  value,\n  onChangeText,\n  placeholder,\n  error,\n  loading = false,\n  secure = false,\n  testID,\n  accessibilityLabel,\n}: TextFieldProps) {\n  const s = useStyles();\n  return (\n    <View style={s.fieldWrap} testID={testID}>\n      <Text style={s.fieldLabel}>{label}</Text>\n      <View style={s.fieldRow}>\n        <TextInput\n          style={[s.input, error !== undefined && s.inputError]}\n          value={value}\n          onChangeText={onChangeText}\n          placeholder={placeholder}\n          secureTextEntry={secure}\n          accessibilityLabel={accessibilityLabel ?? label}\n        />\n        {loading && <ActivityIndicator size=\"small\" style={s.fieldSpinner} />}\n      </View>\n      {error !== undefined && (\n        <Text style={s.fieldError} accessibilityRole=\"alert\">\n          {error}\n        </Text>\n      )}\n    </View>\n  );\n}\n\nexport function ListRow({\n  title,\n  subtitle,\n  badge,\n  trailing,\n  leading,\n  onPress,\n  testID,\n  accessibilityLabel,\n}: ListRowProps) {\n  const s = useStyles();\n  const body = (\n    <>\n      {leading !== undefined && <View style={s.rowLeading}>{leading}</View>}\n      <View style={s.rowBody}>\n        <Text style={s.rowTitle}>{title}</Text>\n        {subtitle !== undefined && <Text style={s.rowSubtitle}>{subtitle}</Text>}\n        {badge !== undefined && <Badge label={badge} />}\n      </View>\n      {trailing !== undefined && <Text style={s.rowTrailing}>{trailing}</Text>}\n    </>\n  );\n  if (onPress === undefined) {\n    return (\n      <View style={s.row} testID={testID} accessibilityLabel={accessibilityLabel}>\n        {body}\n      </View>\n    );\n  }\n  return (\n    <Pressable\n      style={s.row}\n      onPress={onPress}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? title}\n    >\n      {body}\n    </Pressable>\n  );\n}\n\nexport function Badge({ label, tone = \"info\", testID, accessibilityLabel }: BadgeProps) {\n  const s = useStyles();\n  return (\n    <View style={s.badge} testID={testID} accessibilityLabel={accessibilityLabel}>\n      <Text\n        style={[\n          s.badgeText,\n          tone === \"success\" && s.badgeSuccess,\n          tone === \"warn\" && s.badgeWarn,\n          tone === \"error\" && s.badgeError,\n        ]}\n      >\n        {label}\n      </Text>\n    </View>\n  );\n}\n\nexport function StateView({\n  state,\n  title,\n  message,\n  actionLabel,\n  onAction,\n  testID,\n  accessibilityLabel,\n}: StateViewProps) {\n  const s = useStyles();\n  return (\n    <View\n      style={s.stateWrap}\n      testID={testID}\n      accessibilityLabel={accessibilityLabel ?? title}\n      accessibilityRole={state === \"error\" ? \"alert\" : undefined}\n    >\n      {state === \"loading\" && <ActivityIndicator size=\"large\" />}\n      <Text style={[s.stateTitle, state === \"error\" && s.stateTitleError]}>{title}</Text>\n      {message !== undefined && <Text style={s.stateMessage}>{message}</Text>}\n      {actionLabel !== undefined && onAction !== undefined && (\n        <AppButton label={actionLabel} onPress={onAction} kind=\"ghost\" />\n      )}\n    </View>\n  );\n}\n\nexport function Spinner({ size = \"small\", testID, accessibilityLabel }: SpinnerProps) {\n  return (\n    <ActivityIndicator size={size} testID={testID} accessibilityLabel={accessibilityLabel} />\n  );\n}\n\n// Conformité au contrat vérifiée par le compilateur (patron du banc P-003).\nexport const primitives: Primitives = {\n  ScreenShell,\n  Section,\n  AppText,\n  AppButton,\n  TextField,\n  ListRow,\n  Badge,\n  StateView,\n  Spinner,\n};\n",
  "lib/primitives/styles.ts": "// FEUILLES DE STYLE — StyleSheet + tokens maison (D-021). SEUL module (avec\n// primitives.tsx) à connaître le moteur de styling : les contrats n'en savent\n// rien (étanchéité §22). Tokens consommés depuis la SOURCE UNIQUE (3.1).\n// RTL : propriétés LOGIQUES exclusivement (start/end) — miroir automatique\n// prouvé au banc, verrouillé par tests/rtl-ratchet.test.ts.\nimport { theme } from \"../tokens\";\nimport { StyleSheet } from \"react-native\";\nimport type { Scheme } from \"./contracts.ts\";\n\nexport type Palette = (typeof theme.color)[Scheme];\n\nconst makeSheet = (c: Palette) =>\n  StyleSheet.create({\n    // — ScreenShell —\n    shell: { flex: 1, backgroundColor: c.bg },\n    shellTitle: {\n      fontSize: theme.font.heading,\n      fontWeight: \"700\",\n      color: c.text,\n      padding: theme.space.lg,\n    },\n    // — Section —\n    section: { padding: theme.space.lg },\n    sectionTitle: {\n      fontSize: theme.font.title,\n      fontWeight: \"600\",\n      color: c.text,\n      marginBottom: theme.space.md,\n    },\n    // — AppText (variantes = tokens de police ; tons = tokens de couleur) —\n    textLabel: { fontSize: theme.font.label, color: c.text },\n    textBody: { fontSize: theme.font.body, color: c.text },\n    textTitle: { fontSize: theme.font.title, fontWeight: \"600\", color: c.text },\n    textHeading: { fontSize: theme.font.heading, fontWeight: \"700\", color: c.text },\n    toneMuted: { color: c.muted },\n    tonePrimary: { color: c.primary },\n    toneError: { color: c.error },\n    toneSuccess: { color: c.success },\n    toneWarn: { color: c.warn },\n    alignStart: { textAlign: \"auto\" },\n    alignCenter: { textAlign: \"center\" },\n    // `justify` n'existe pas ; « end » logique = right en LTR, miroir en RTL\n    // est géré par writingDirection native — on utilise l'axe logique :\n    alignEnd: { alignSelf: \"flex-end\" },\n    // — AppButton —\n    button: {\n      backgroundColor: c.primary,\n      borderRadius: theme.radius.md,\n      paddingVertical: theme.space.md,\n      paddingHorizontal: theme.space.lg,\n      alignItems: \"center\",\n      flexDirection: \"row\",\n      justifyContent: \"center\",\n      gap: theme.space.sm,\n    },\n    buttonGhost: {\n      backgroundColor: \"transparent\",\n      borderWidth: 1,\n      borderColor: c.primary,\n    },\n    buttonDisabled: { opacity: 0.5 },\n    buttonText: { color: c.onPrimary, fontWeight: \"600\", fontSize: theme.font.body },\n    buttonGhostText: { color: c.primary },\n    // — TextField —\n    fieldWrap: { marginBottom: theme.space.md },\n    fieldLabel: {\n      fontSize: theme.font.label,\n      color: c.muted,\n      marginBottom: theme.space.xs,\n    },\n    fieldRow: { flexDirection: \"row\", alignItems: \"center\" },\n    input: {\n      flex: 1,\n      borderWidth: 1,\n      borderColor: c.border,\n      borderRadius: theme.radius.sm,\n      paddingHorizontal: theme.space.md,\n      paddingVertical: theme.space.sm,\n      color: c.text,\n      backgroundColor: c.surface,\n      fontSize: theme.font.body,\n    },\n    inputError: { borderColor: c.error },\n    fieldError: {\n      color: c.error,\n      fontSize: theme.font.label,\n      marginTop: theme.space.xs,\n    },\n    fieldSpinner: { marginStart: theme.space.sm },\n    // — ListRow —\n    row: {\n      backgroundColor: c.surface,\n      borderColor: c.border,\n      borderWidth: 1,\n      borderRadius: theme.radius.md,\n      padding: theme.space.md,\n      marginHorizontal: theme.space.lg,\n      marginVertical: theme.space.xs,\n      flexDirection: \"row\",\n      alignItems: \"center\",\n    },\n    rowLeading: { marginEnd: theme.space.md },\n    rowBody: { flex: 1 },\n    rowTitle: { fontSize: theme.font.body, fontWeight: \"600\", color: c.text },\n    rowSubtitle: {\n      fontSize: theme.font.label,\n      color: c.muted,\n      marginTop: theme.space.xs,\n    },\n    rowTrailing: {\n      fontSize: theme.font.body,\n      fontWeight: \"700\",\n      color: c.primary,\n      marginStart: theme.space.md,\n    },\n    // — Badge —\n    badge: {\n      backgroundColor: c.badgeBg,\n      borderRadius: theme.radius.sm,\n      paddingHorizontal: theme.space.sm,\n      paddingVertical: 2,\n      alignSelf: \"flex-start\",\n      marginTop: theme.space.xs,\n    },\n    badgeText: { fontSize: theme.font.label, color: c.muted },\n    badgeSuccess: { color: c.success },\n    badgeWarn: { color: c.warn },\n    badgeError: { color: c.error },\n    // — StateView —\n    stateWrap: {\n      flex: 1,\n      alignItems: \"center\",\n      justifyContent: \"center\",\n      padding: theme.space.xl,\n      gap: theme.space.md,\n    },\n    stateTitle: {\n      fontSize: theme.font.title,\n      fontWeight: \"600\",\n      color: c.text,\n      textAlign: \"center\",\n    },\n    stateMessage: {\n      fontSize: theme.font.body,\n      color: c.muted,\n      textAlign: \"center\",\n    },\n    stateTitleError: { color: c.error },\n  });\n\nexport type Sheet = ReturnType<typeof makeSheet>;\n\n// Pré-calcul UNIQUE des deux feuilles (patron gagnant du banc : la bascule\n// de thème ne recrée aucun style, elle change de feuille).\nexport const SHEETS: Record<Scheme, Sheet> = {\n  light: makeSheet(theme.color.light),\n  dark: makeSheet(theme.color.dark),\n};\n",
  "lib/primitives/theme-bridge.tsx": "// PONT DE THÈME (D1, dossier 3.2 validé) — patron GAGNANT du banc P-003\n// (bascule light/dark en 2 frames : les deux feuilles de style sont\n// pré-calculées une fois au chargement, la bascule ne fait que changer de\n// feuille via le contexte). Liaison STATIQUE aux tokens : la variance par\n// app est un acte de COMPILATION (le compilateur émettra un module de\n// tokens propre à chaque app — modèle copie-régénérable §3), jamais un\n// mécanisme runtime.\nimport { createContext, useContext, useMemo, useState } from \"react\";\nimport type { PropsWithChildren } from \"react\";\nimport type { Scheme, ThemeBridge } from \"./contracts.ts\";\nimport { SHEETS, type Sheet } from \"./styles.ts\";\n\nconst SchemeContext = createContext<ThemeBridge>({\n  scheme: \"light\",\n  setScheme: () => undefined,\n});\n\nexport function ThemeRoot({\n  children,\n  initialScheme = \"light\",\n}: PropsWithChildren<{ initialScheme?: Scheme }>) {\n  const [scheme, setScheme] = useState<Scheme>(initialScheme);\n  const value = useMemo(() => ({ scheme, setScheme }), [scheme]);\n  return <SchemeContext.Provider value={value}>{children}</SchemeContext.Provider>;\n}\n\nexport function useThemeBridge(): ThemeBridge {\n  return useContext(SchemeContext);\n}\n\nexport function useStyles(): Sheet {\n  return SHEETS[useContext(SchemeContext).scheme];\n}\n",
  "lib/runtime/air-runtime.tsx": "// RUNTIME COPIÉ (compilateur 4.3, D-026 Option C) — pont UNIQUE et TESTÉ\n// entre les données canoniques d'écran (modules .data générés) et les\n// contrats des Smart Blocks gelés. Les écrans générés restent du code\n// STRUCTUREL lisible (séquence de blocs explicite, points d'insertion de\n// slots) ; toute la logique de correspondance vit ici, écrite une fois.\n// F3 : AUCUN texte naturel dans ce module — tous les libellés viennent des\n// données AIR ; les erreurs internes sont des codes.\n// Effets d'actions en v1 compilateur : `navigate` est câblé ; les effets\n// `capability`/`mutation`/`slot` sont des non-opérations STRUCTURÉES\n// (implémentations : Phases 5+/9 — lecture consignée D-028).\nimport { useMemo, useState } from \"react\";\nimport { useNavigation } from \"@react-navigation/native\";\nimport {\n  ButtonBlock,\n  DetailHeaderBlock,\n  EmptyStateBlock,\n  FormBlock,\n  HeaderBlock,\n  ListBlock,\n} from \"../blocks/components\";\nimport type { FormFieldSpec, ListItemData } from \"../blocks/contracts\";\nimport { useDataProvider } from \"./data-provider\";\n\nexport interface AirEffectData {\n  kind: \"navigate\" | \"capability\" | \"mutation\" | \"slot\";\n  screenId?: string;\n}\n\nexport interface AirBlockInstanceData {\n  id: string;\n  blockType: string;\n  entityId?: string;\n  props: Readonly<Record<string, unknown>>;\n}\n\nexport interface AirFieldData {\n  id: string;\n  name: string;\n  type: string;\n}\n\nexport interface AirScreenData {\n  screenId: string;\n  title: string;\n  blocks: readonly AirBlockInstanceData[];\n  actions: Readonly<Record<string, AirEffectData>>;\n  uiActionsByBlock: Readonly<Record<string, string>>;\n  entities: Readonly<Record<string, { fields: readonly AirFieldData[] }>>;\n}\n\nexport interface AirScreenProps {\n  route?: { params?: { itemId?: string } };\n}\n\ninterface BlockRef {\n  screen: AirScreenData;\n  blockId: string;\n}\n\nfunction block(screen: AirScreenData, blockId: string): AirBlockInstanceData {\n  const found = screen.blocks.find((b) => b.id === blockId);\n  if (found === undefined) throw new Error(`AIR_RUNTIME_BLOCK_MISSING:${blockId}`);\n  return found;\n}\n\nfunction str(value: unknown): string | undefined {\n  return typeof value === \"string\" ? value : undefined;\n}\n\nfunction useDispatch(screen: AirScreenData) {\n  const navigation = useNavigation();\n  return useMemo(\n    () => (actionId: string | undefined) => {\n      if (actionId === undefined) return;\n      const effect = screen.actions[actionId];\n      if (effect?.kind === \"navigate\" && effect.screenId !== undefined) {\n        (navigation.navigate as (name: string) => void)(effect.screenId);\n      }\n      // capability / mutation / slot : non-opération v1 (Phases 5+/9).\n    },\n    [navigation, screen],\n  );\n}\n\nfunction useItemNavigate(screen: AirScreenData, blockId: string) {\n  const navigation = useNavigation();\n  const actionId = screen.uiActionsByBlock[blockId];\n  const effect = actionId === undefined ? undefined : screen.actions[actionId];\n  return (itemId: string) => {\n    if (effect?.kind === \"navigate\" && effect.screenId !== undefined) {\n      (\n        navigation.navigate as (name: string, params: { itemId: string }) => void\n      )(effect.screenId, { itemId });\n    }\n  };\n}\n\nexport function AirHeader({ screen, blockId }: BlockRef) {\n  const b = block(screen, blockId);\n  const title = str(b.props.title);\n  if (title === undefined) throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:title`);\n  return <HeaderBlock testID={b.id} title={title} subtitle={str(b.props.subtitle)} />;\n}\n\nexport function AirButton({ screen, blockId }: BlockRef) {\n  const b = block(screen, blockId);\n  const dispatch = useDispatch(screen);\n  const label = str(b.props.label);\n  const actionId = str(b.props.actionId);\n  if (label === undefined || actionId === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:label|actionId`);\n  }\n  const kind = b.props.kind === \"ghost\" ? (\"ghost\" as const) : (\"primary\" as const);\n  return (\n    <ButtonBlock testID={b.id} label={label} kind={kind} onPress={() => dispatch(actionId)} />\n  );\n}\n\nexport function AirEmptyState({ screen, blockId }: BlockRef) {\n  const b = block(screen, blockId);\n  const dispatch = useDispatch(screen);\n  const title = str(b.props.title);\n  if (title === undefined) throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:title`);\n  const actionId = str(b.props.actionId);\n  return (\n    <EmptyStateBlock\n      testID={b.id}\n      title={title}\n      message={str(b.props.message)}\n      actionLabel={str(b.props.actionLabel)}\n      onAction={actionId === undefined ? undefined : () => dispatch(actionId)}\n    />\n  );\n}\n\nexport function AirDetailHeader({\n  screen,\n  blockId,\n  itemId,\n}: BlockRef & { itemId?: string }) {\n  const b = block(screen, blockId);\n  const provider = useDataProvider();\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const instance = provider.getInstance(b.entityId, itemId);\n  const value = (fieldId: unknown): string =>\n    typeof fieldId === \"string\" ? (instance?.values[fieldId] ?? \"\") : \"\";\n  const badgeIds = Array.isArray(b.props.badgeFieldIds) ? b.props.badgeFieldIds : undefined;\n  return (\n    <DetailHeaderBlock\n      testID={b.id}\n      title={value(b.props.titleFieldId)}\n      subtitle={\n        b.props.subtitleFieldId === undefined ? undefined : value(b.props.subtitleFieldId)\n      }\n      badges={badgeIds?.map((id) => value(id))}\n      trailing={\n        b.props.trailingFieldId === undefined ? undefined : value(b.props.trailingFieldId)\n      }\n    />\n  );\n}\n\nexport function AirList({ screen, blockId }: BlockRef) {\n  const b = block(screen, blockId);\n  const provider = useDataProvider();\n  const onItemNavigate = useItemNavigate(screen, blockId);\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const titleFieldId = str(b.props.titleFieldId);\n  if (titleFieldId === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:titleFieldId`);\n  }\n  const instances = provider.listInstances(b.entityId);\n  const pick = (fieldId: unknown, values: Readonly<Record<string, string>>) =>\n    typeof fieldId === \"string\" ? values[fieldId] : undefined;\n  const items: ListItemData[] = instances.map((instance) => ({\n    id: instance.id,\n    title: instance.values[titleFieldId] ?? \"\",\n    subtitle: pick(b.props.subtitleFieldId, instance.values),\n    trailing: pick(b.props.trailingFieldId, instance.values),\n    badge: pick(b.props.badgeFieldId, instance.values),\n  }));\n  const emptyTitle = str(b.props.emptyTitle);\n  const state =\n    items.length === 0 && emptyTitle !== undefined\n      ? ({ kind: \"empty\", title: emptyTitle, message: str(b.props.emptyMessage) } as const)\n      : ({ kind: \"ready\" } as const);\n  return (\n    <ListBlock\n      testID={b.id}\n      title={str(b.props.title)}\n      items={items}\n      state={state}\n      onItemPress={onItemNavigate}\n    />\n  );\n}\n\nexport function AirForm({ screen, blockId }: BlockRef) {\n  const b = block(screen, blockId);\n  const dispatch = useDispatch(screen);\n  const [values, setValues] = useState<Readonly<Record<string, string>>>({});\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const fieldsById = new Map(\n    (screen.entities[b.entityId]?.fields ?? []).map((f) => [f.id, f]),\n  );\n  const fieldIds = Array.isArray(b.props.fieldIds) ? b.props.fieldIds : [];\n  // Lecture D-028 : l'AIR v1 ne porte pas de libellés humains de champs —\n  // le libellé rendu est `field.name` (donnée AIR), jamais un texte moteur.\n  const fields: FormFieldSpec[] = fieldIds.flatMap((fieldId) => {\n    if (typeof fieldId !== \"string\") return [];\n    const field = fieldsById.get(fieldId);\n    return field === undefined ? [] : [{ id: field.id, label: field.name }];\n  });\n  const submitLabel = str(b.props.submitLabel);\n  if (submitLabel === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:submitLabel`);\n  }\n  const actionId = screen.uiActionsByBlock[blockId];\n  return (\n    <FormBlock\n      testID={b.id}\n      title={str(b.props.title)}\n      fields={fields}\n      values={values}\n      onChangeField={(fieldId, value) =>\n        setValues((prev) => ({ ...prev, [fieldId]: value }))\n      }\n      submitLabel={submitLabel}\n      onSubmit={() => dispatch(actionId)}\n      state=\"ready\"\n    />\n  );\n}\n",
  "lib/runtime/data-provider.tsx": "// RUNTIME COPIÉ (compilateur 4.3, D-026 S2/§15) — INTERFACE de données du\n// projet généré. Contrat obligatoire dès le premier provider : le code\n// généré ne dépend JAMAIS d'un provider concret. Implémentation par\n// défaut : VIDE (déterministe). L'implémentation `demo` (fixtures\n// déterministes seedées par contentHash) arrive en 4.5 ; Supabase en\n// Phase 5 — sans changement de cette interface.\n// Ce fichier est un ARTEFACT DE SORTIE du compilateur (copie régénérable,\n// D-007) : jamais édité dans un projet généré.\nimport { createContext, useContext } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n\nexport interface EntityInstance {\n  id: string;\n  values: Readonly<Record<string, string>>;\n}\n\nexport interface DataProvider {\n  listInstances(entityId: string): readonly EntityInstance[];\n  getInstance(entityId: string, instanceId?: string): EntityInstance | undefined;\n}\n\nexport const EMPTY_DATA_PROVIDER: DataProvider = {\n  listInstances: () => [],\n  getInstance: () => undefined,\n};\n\nconst DataContext = createContext<DataProvider>(EMPTY_DATA_PROVIDER);\n\nexport function DataRoot({\n  provider,\n  children,\n}: PropsWithChildren<{ provider: DataProvider }>) {\n  return <DataContext.Provider value={provider}>{children}</DataContext.Provider>;\n}\n\nexport function useDataProvider(): DataProvider {\n  return useContext(DataContext);\n}\n",
  "lib/runtime/demo-provider.ts": "// RUNTIME COPIÉ (compilateur 4.5, D-026 S2/D-030) — provider `demo` :\n// les lignes de démonstration sont GÉNÉRÉES À LA COMPILATION (module\n// canonique demo.data.ts, fonction pure seedée par le contentHash du\n// dataset — D-013 : preview = données de démo uniquement) ; ce module ne\n// fait que les SERVIR derrière l'interface DataProvider (§15). Instance\n// par défaut d'un écran de détail sans paramètre = PREMIÈRE ligne\n// (déterministe, lecture D-030).\nimport type { DataProvider, EntityInstance } from \"./data-provider\";\n\nexport type DemoData = Readonly<Record<string, readonly EntityInstance[]>>;\n\nexport function buildDemoProvider(data: DemoData): DataProvider {\n  return {\n    listInstances: (entityId) => data[entityId] ?? [],\n    getInstance: (entityId, instanceId) => {\n      const rows = data[entityId] ?? [];\n      if (instanceId === undefined) return rows[0];\n      return rows.find((r) => r.id === instanceId);\n    },\n  };\n}\n",
  "lib/tokens/index.ts": "// RUNTIME COPIÉ (compilateur 4.3) — point d'entrée tokens du projet\n// généré : ré-exporte le thème GÉNÉRÉ (données pures, scellé 3.1) sans\n// tirer zod ni le schéma (moteur uniquement).\nexport { theme } from \"./theme.generated\";\n",
  "lib/tokens/theme.generated.ts": "// GÉNÉRÉ par scripts/generate.mjs depuis tokens.json — NE PAS ÉDITER.\n// Thème React Native (D-021 : StyleSheet + tokens maison) — données pures,\n// aucune dépendance de bibliothèque de styling (ARCHITECTURE §22, D-021 :\n// le choix de styling ne fuite jamais dans les contrats ni dans ce module).\nexport const theme = {\n  \"color\": {\n    \"light\": {\n      \"bg\": \"#F6F7F9\",\n      \"surface\": \"#FFFFFF\",\n      \"text\": \"#16181D\",\n      \"muted\": \"#5A616E\",\n      \"primary\": \"#FA5D1E\",\n      \"onPrimary\": \"#FFFFFF\",\n      \"border\": \"#D9DDE3\",\n      \"error\": \"#C42B1C\",\n      \"success\": \"#1F7A3D\",\n      \"warn\": \"#8A6D00\",\n      \"badgeBg\": \"#EEF1F5\"\n    },\n    \"dark\": {\n      \"bg\": \"#0A050E\",\n      \"surface\": \"#17121C\",\n      \"text\": \"#F2F0F4\",\n      \"muted\": \"#A49FAC\",\n      \"primary\": \"#FA5D1E\",\n      \"onPrimary\": \"#FFFFFF\",\n      \"border\": \"#2E2836\",\n      \"error\": \"#FF6B5E\",\n      \"success\": \"#4CC17A\",\n      \"warn\": \"#E3C25A\",\n      \"badgeBg\": \"#241E2B\"\n    }\n  },\n  \"space\": {\n    \"xs\": 4,\n    \"sm\": 8,\n    \"md\": 12,\n    \"lg\": 16,\n    \"xl\": 24\n  },\n  \"radius\": {\n    \"sm\": 6,\n    \"md\": 10,\n    \"lg\": 16\n  },\n  \"font\": {\n    \"label\": 12,\n    \"body\": 14,\n    \"title\": 17,\n    \"heading\": 22\n  }\n} as const;\nexport type SchemeName = keyof typeof theme.color;\nexport type Palette = (typeof theme.color)[SchemeName];\n",
};

export const EMBEDDED_ASSETS_FINGERPRINT = "8b9d3fbc867b5359d73d200db68f7b57566dffb25a26130174f6a83374c22b3c";
